  "notes": [
   "සන්නයේ අභිභූ වරනැඟීම චතුත්ථිය දක්වා දී 'ඉච්චාදි' යයි නවතී; 'සෙසං භික්ඛුසද්දසමං, රස්සත්තමෙව විසෙසො' අනුව සෙසු රූප සකස් කර ඇත.",
   "හ්‍රස්ව කළ හෙයින් (කතරස්ස) අකාරය හා 'වෙ' ආදේශය නොවේ: අභිභුවො.",
   "සබ්බඤ්ඤූ: යො හට නො ආදේශය පමණක් විශේෂයි — සබ්බඤ්ඤූ සබ්බඤ්ඤුනො. සහභූ: සහභූ සහභුවො සහභුනො."
  ],
