   "පොතේ දැක්වෙන නමුත් සාධන සූත්‍රය මෙහි ඇතුළත් නොකළ රූප: ආදිං, ආදෙ.",
   "ආදිං, ආදෙ (සත්තමී): පොතේ දැක්වුණත් මෙයට නිශ්චිත සූත්‍රයක් දත්ත ගොනුවල නොමැති හෙයින් සාධනය දක්වා නැත."
